-- Domain 17: Sales Tax | functions
-- Generated by tools/split_by_domain.py. Statements keep their original order tag (@seq).

-- @seq 325
CREATE FUNCTION public.acct_tax_chain(p_jurisdiction_id uuid) RETURNS TABLE(jurisdiction_id uuid, depth integer, level text)
    LANGUAGE sql STABLE
    AS $$
  WITH RECURSIVE c AS (
    SELECT id, parent_id, 0 AS depth, level FROM acct_tax_jurisdictions WHERE id = p_jurisdiction_id
    UNION ALL
    SELECT j.id, j.parent_id, c.depth + 1, j.level FROM acct_tax_jurisdictions j JOIN c ON j.id = c.parent_id WHERE c.depth < 10)
  SELECT id, depth, level FROM c;
$$;

-- @seq 578
CREATE FUNCTION public.tax_nexus_exposure(p_tenant_id uuid, p_as_of date DEFAULT CURRENT_DATE, p_entity_id uuid DEFAULT NULL::uuid) RETURNS TABLE(state_code text, state_name text, window_label text, w_from date, w_to date, counted_sales numeric, counted_txns bigint, marketplace_sales numeric, sales_threshold numeric, txn_threshold integer, threshold_logic text, pct_of_threshold numeric, exceeded boolean, registered boolean, status text, note text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_entity uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  v_entity := coalesce(p_entity_id, acct_default_entity(p_tenant_id));
  RETURN QUERY
  WITH w AS (
    SELECT s.*, x.window_label, x.w_from, x.w_to FROM tax_us_states s CROSS JOIN LATERAL tax_us_windows(s.measurement_window, p_as_of) x
  ), m AS (
    SELECT w.*, coalesce(sb.direct_sales,0) + CASE WHEN w.marketplace_sales_count THEN coalesce(sb.marketplace_sales,0) ELSE 0 END AS c_sales,
           coalesce(sb.direct_txns,0) + CASE WHEN w.marketplace_sales_count THEN coalesce(sb.marketplace_txns,0) ELSE 0 END AS c_txns,
           coalesce(sb.marketplace_sales,0) AS m_sales
      FROM w LEFT JOIN LATERAL (SELECT * FROM tax_us_sales_by_state(p_tenant_id, w.w_from, w.w_to) z WHERE z.state_code = w.state_code) sb ON true
  ), e AS (
    SELECT m.*,
      CASE WHEN m.threshold_strict THEN m.c_sales > m.econ_sales_threshold ELSE m.c_sales >= m.econ_sales_threshold END AS hit_sales,
      CASE WHEN m.econ_txn_threshold IS NULL THEN NULL
           WHEN m.threshold_strict THEN m.c_txns > m.econ_txn_threshold ELSE m.c_txns >= m.econ_txn_threshold END AS hit_txns
      FROM m
  ), r AS (
    SELECT e.*,
      CASE WHEN e.econ_sales_threshold IS NULL THEN false
           WHEN e.threshold_logic = 'and' THEN e.hit_sales AND e.hit_txns
           WHEN e.threshold_logic = 'or'  THEN e.hit_sales OR e.hit_txns
           ELSE e.hit_sales END AS hit,
      greatest(CASE WHEN e.econ_sales_threshold > 0 THEN e.c_sales / e.econ_sales_threshold END,
               CASE WHEN e.econ_txn_threshold > 0 AND e.threshold_logic = 'or' THEN e.c_txns::numeric / e.econ_txn_threshold END) AS pct,
      EXISTS (SELECT 1 FROM acct_tax_nexus n JOIN acct_tax_jurisdictions j ON j.id = n.jurisdiction_id
               WHERE n.tenant_id = p_tenant_id AND n.entity_id = v_entity AND j.state_code = e.state_code AND j.level = 'state'
                 AND n.collect_tax AND (n.effective_to IS NULL OR n.effective_to >= p_as_of)) AS reg
      FROM e
  )
  SELECT r.state_code, r.name, r.window_label, r.w_from, r.w_to, r.c_sales, r.c_txns, r.m_sales,
         r.econ_sales_threshold, r.econ_txn_threshold, r.threshold_logic, round(coalesce(r.pct,0) * 100, 1), r.hit, r.reg,
         CASE WHEN r.econ_sales_threshold IS NULL THEN 'no_sales_tax'
              WHEN r.reg THEN 'registered'
              WHEN r.hit THEN 'exceeded_not_registered'
              WHEN coalesce(r.pct,0) >= 0.8 THEN 'approaching'
              ELSE 'below' END,
         concat_ws('; ', r.notes,
           CASE WHEN r.sales_basis <> 'gross' THEN 'Threshold uses ' || r.sales_basis || ' sales; figure shown is gross (upper bound)' END,
           CASE WHEN r.m_sales > 0 AND NOT coalesce(r.marketplace_sales_count,false) THEN 'Marketplace sales excluded by this state' END)
    FROM r ORDER BY r.state_code, r.w_from;
END $$;

-- @seq 579
CREATE FUNCTION public.tax_refresh_nexus_alerts(p_tenant_id uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_entity uuid := acct_default_entity(p_tenant_id); v_n int := 0; r record;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  FOR r IN SELECT DISTINCT ON (x.state_code) x.* FROM tax_nexus_exposure(p_tenant_id, p_as_of, v_entity) x
            ORDER BY x.state_code, (x.status = 'exceeded_not_registered') DESC, x.pct_of_threshold DESC LOOP
    IF r.status IN ('approaching','exceeded_not_registered') THEN
      INSERT INTO tax_nexus_alerts(tenant_id, entity_id, state_code, status, window_label, w_from, w_to, counted_sales, counted_txns, pct_of_threshold)
      VALUES (p_tenant_id, v_entity, r.state_code, r.status, r.window_label, r.w_from, r.w_to, r.counted_sales, r.counted_txns, r.pct_of_threshold)
      ON CONFLICT (tenant_id, entity_id, state_code) DO UPDATE SET status = EXCLUDED.status, window_label = EXCLUDED.window_label,
        w_from = EXCLUDED.w_from, w_to = EXCLUDED.w_to, counted_sales = EXCLUDED.counted_sales, counted_txns = EXCLUDED.counted_txns,
        pct_of_threshold = EXCLUDED.pct_of_threshold, last_checked_at = now(),
        acknowledged_at = CASE WHEN tax_nexus_alerts.status <> EXCLUDED.status THEN NULL ELSE tax_nexus_alerts.acknowledged_at END;
      v_n := v_n + 1;
    ELSE
      UPDATE tax_nexus_alerts SET status = 'resolved', last_checked_at = now(), resolution = coalesce(resolution, r.status)
       WHERE tenant_id = p_tenant_id AND entity_id = v_entity AND state_code = r.state_code AND status <> 'resolved';
    END IF;
  END LOOP;
  RETURN v_n;
END $$;

-- @seq 580
CREATE FUNCTION public.tax_us_sales_by_state(p_tenant_id uuid, p_from date, p_to date) RETURNS TABLE(state_code text, direct_sales numeric, direct_txns bigint, marketplace_sales numeric, marketplace_txns bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  RETURN QUERY
  WITH docs AS (
    SELECT upper(a.state) AS st, (o.subtotal - o.discount_total) AS amt, o.is_marketplace_facilitated AS mkt
      FROM erp_orders o
      JOIN LATERAL (SELECT x.state FROM erp_order_addresses x
                     WHERE x.order_id = o.id AND x.address_type = 'shipping' AND x.country_code IN ('US','USA')
                     ORDER BY x.created_at DESC LIMIT 1) a ON true
     WHERE o.tenant_id = p_tenant_id AND o.order_date::date BETWEEN p_from AND p_to
       AND lower(o.status) NOT IN ('cancelled','canceled','void','voided','draft','abandoned')
    UNION ALL
    SELECT upper(i.ship_to_state), (i.subtotal - coalesce(i.discount_total,0)), false
      FROM acct_ar_invoices i
     WHERE i.tenant_id = p_tenant_id AND i.invoice_date BETWEEN p_from AND p_to
       AND i.ship_to_state IS NOT NULL AND coalesce(i.ship_to_country,'US') IN ('US','USA')
       AND i.status NOT IN ('draft','void')
  )
  SELECT d.st, coalesce(sum(d.amt) FILTER (WHERE NOT d.mkt),0), count(*) FILTER (WHERE NOT d.mkt),
         coalesce(sum(d.amt) FILTER (WHERE d.mkt),0), count(*) FILTER (WHERE d.mkt)
    FROM docs d WHERE d.st ~ '^[A-Z]{2}$' GROUP BY d.st;
END $_$;

-- @seq 581
CREATE FUNCTION public.tax_us_windows(p_window text, p_as_of date) RETURNS TABLE(window_label text, w_from date, w_to date)
    LANGUAGE sql IMMUTABLE
    AS $$
  WITH b AS (SELECT date_trunc('year', p_as_of)::date AS cy, date_trunc('quarter', p_as_of)::date AS cq)
  SELECT 'previous calendar year', (cy - interval '1 year')::date, cy - 1 FROM b WHERE p_window IN ('prev_or_current_cy','prev_cy')
  UNION ALL SELECT 'current calendar year to date', cy, p_as_of FROM b WHERE p_window = 'prev_or_current_cy'
  UNION ALL SELECT 'prior 12 months', (p_as_of - interval '12 months')::date + 1, p_as_of FROM b WHERE p_window = 'prior_12m'
  UNION ALL SELECT 'prior four completed quarters', (cq - interval '12 months')::date, cq - 1 FROM b WHERE p_window = 'prior_4q'
  UNION ALL SELECT '12 months ending September 30',
         (make_date(CASE WHEN p_as_of >= make_date(extract(year FROM p_as_of)::int,9,30) THEN extract(year FROM p_as_of)::int ELSE extract(year FROM p_as_of)::int - 1 END, 9, 30) - interval '12 months')::date + 1,
         make_date(CASE WHEN p_as_of >= make_date(extract(year FROM p_as_of)::int,9,30) THEN extract(year FROM p_as_of)::int ELSE extract(year FROM p_as_of)::int - 1 END, 9, 30)
    FROM b WHERE p_window = 'ct_sep30';
$$;

